import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA source implementing cumulative product along a given dimension.
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void cumprod_kernel(const __half* __restrict__ in,
                               __half* __restrict__ out,
                               int64_t rows,
                               int64_t cols) {
    int64_t row = blockIdx.x;
    if (row >= rows) return;

    const __half* in_row  = in + row * cols;
    __half*       out_row = out + row * cols;

    float acc = 1.0f;
    #pragma unroll 4
    for (int64_t i = 0; i < cols; ++i) {
        acc *= __half2float(in_row[i]);
        out_row[i] = __float2half(acc);
    }
}

void cumprod_forward(torch::Tensor input,
                     torch::Tensor output,
                     int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(output.is_cuda(), "output must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kHalf,
                "input must be of type torch.float16");
    TORCH_CHECK(output.scalar_type() == torch::kHalf,
                "output must be of type torch.float16");
    TORCH_CHECK(dim >= 0 && dim < input.dim(),
                "dim out of range");

    // Collapse all dimensions except the one we are reducing over.
    int64_t rows = 1;
    int64_t cols = input.size(dim);
    for (int64_t i = 0; i < input.dim(); ++i) {
        if (i != dim) rows *= input.size(i);
    }

    const dim3 grid(rows);
    const dim3 block(1);

    cumprod_kernel<<<grid, block>>>(
        static_cast<const __half*>(input.data_ptr()),
        static_cast<__half*>(output.data_ptr()),
        rows,
        cols
    );

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("cumprod_forward", &cumprod_forward,
          "Cumulative product forward (CUDA)");
}
'''

# Compile the inline extension
cumprod_cuda = load_inline(
    name='cumprod_cuda',
    cpp_sources=[],
    cuda_sources=[cuda_source],
    functions=['cumprod_forward'],
    verbose=False,
)

