# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model that computes the cumulative
    product along a specified dimension using a custom CUDA kernel.
    """

    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure fp16 and CUDA, and make contiguous for the kernel.
        x = x.to(dtype=torch.float16, device='cuda', non_blocking=True).contiguous()
        out = torch.empty_like(x)
        cumprod_cuda.cumprod_forward(x, out, self.dim)
        return out

# ----------------------------------------------------------------------
# Helper functions matching the reference API
# ----------------------------------------------------------------------
def get_inputs():
    # batch_size = 32768, input_shape = (32768,)
    return [torch.rand(32768, 32768, device='cuda', dtype=torch.float16)]

def get_init_inputs():
    # dim = 1 (the second dimension)
    return [1]

